<template>
  <div>

    <h1 class="page-title">Blog Posts</h1>

    <div v-if="loading" class="spinner-wrap">
      <div class="spinner"></div>
    </div>

    <div v-else-if="error" class="error-box">
      <p>{{ error }}</p>
      <button @click="fetchPosts(currentPage)">Try again</button>
    </div>

    <div v-else>
      <div v-for="post in posts" :key="post.id" class="post-card">
        <h2 class="post-title">{{ post.title }}</h2>
        <p class="post-excerpt">{{ post.excerpt || post.content.slice(0, 120) + '...' }}</p>
        <router-link :to="'/post/' + post.id" class="read-link">Read more →</router-link>
      </div>

      <div class="pagination">
        <button :disabled="!meta.hasPreviousPage" @click="fetchPosts(currentPage - 1)">← Previous</button>
        <span>Page {{ currentPage }} of {{ meta.totalPages }}</span>
        <button :disabled="!meta.hasNextPage" @click="fetchPosts(currentPage + 1)">Next →</button>
      </div>
    </div>

  </div>
</template>

<script>
import { ref, onMounted } from 'vue'

export default {
  name: 'HomeView',

  setup () {
    const posts = ref([])
    const loading = ref(true)
    const error = ref(null)
    const currentPage = ref(1)
    const meta = ref({})

    async function fetchPosts (page = 1) {
      loading.value = true
      error.value = null

      try {
        const res = await fetch(`https://api.oluwasetemi.dev/posts/?page=${page}&limit=10`)
        if (!res.ok) throw new Error('Failed to fetch posts. Status: ' + res.status)
        const json = await res.json()
        posts.value = json.data
        meta.value = json.meta
        currentPage.value = page
      } catch (err) {
        error.value = err.message
      } finally {
        loading.value = false
      }
    }

    onMounted(() => fetchPosts())

    return { posts, loading, error, currentPage, meta, fetchPosts }
  }
}
</script>

