<template>
  <div id="app-shell">

    <nav class="nav">
      <div class="nav-inner">
        <router-link to="/" class="nav-logo">ECS<span>devblog</span> </router-link>
        <router-link to="/" class="nav-home-link">Home</router-link>
      </div>
    </nav>

    <main class="main">
      <router-view v-slot="{ Component }">
        <Suspense>
          <template #default>
            <component :is="Component" />
          </template>
          <template #fallback>
            <div class="spinner-wrap">
              <div class="spinner"></div>
            </div>
          </template>
        </Suspense>
      </router-view>
    </main>

    <div v-if="appError" class="error-banner">
      <p>Something went wrong. <button @click="appError = null">Dismiss</button></p>
    </div>

  </div>
</template>

<script>
import { ref, onErrorCaptured } from 'vue'

export default {
  name: 'App',

  setup () {
    const appError = ref(null)

    onErrorCaptured((err) => {
      appError.value = err.message
      return false
    })

    return { appError }
  }
}
</script>

